{
  "name": "cache-demo",
  "version": "1.0.0",
  "private": true,
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "build": "turbo run build",
    "lint": "turbo run lint",
    "test": "turbo run test",
    "benchmark": "bash benchmark.sh"
  },
  "devDependencies": {
    "turbo": "latest",
    "typescript": "^5.0.0"
  }
}

export class CoreService {
  private name: string;

  constructor(name: string = 'Core') {
    this.name = name;
  }

  greet(): string {
    return `Hello from ${this.name}!`;
  }

  processData(data: string): string {
    return `Processed: ${data}`;
  }
}

export function coreUtility(input: number): number {
  return input * 2;
}

export function formatDate(date: Date): string {
  return date.toISOString().split('T')[0];
}

export function calculateSum(numbers: number[]): number {
  return numbers.reduce((acc, num) => acc + num, 0);
}

export class Logger {
  log(message: string): void {
    console.log(`[LOG] ${message}`);
  }

  error(message: string): void {
    console.error(`[ERROR] ${message}`);
  }
}

import { CoreService, coreUtility } from '@cache-demo/core';
import { formatDate, calculateSum, Logger } from '@cache-demo/utils';

export class Application {
  private core: CoreService;
  private logger: Logger;

  constructor() {
    this.core = new CoreService('App');
    this.logger = new Logger();
  }

  run(): void {
    this.logger.log(this.core.greet());

    const result = coreUtility(10);
    this.logger.log(`Core utility result: ${result}`);

    const today = formatDate(new Date());
    this.logger.log(`Today's date: ${today}`);

    const sum = calculateSum([1, 2, 3, 4, 5]);
    this.logger.log(`Sum: ${sum}`);

    const processed = this.core.processData('Hello Turborepo!');
    this.logger.log(processed);
  }
}

const app = new Application();
app.run();

